function escAttr(v){return String(v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

const createIcon = (displayName, svgContent, meta) => {
  meta = meta || {};

  const icon = (options) => {
    options = options || {};
    const color = options.color || 'currentColor';
    const size = options.size || 24;
    const className = options.className;
    const attrs = options.attrs || {};

    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
    svg.setAttribute('width', String(size));
    svg.setAttribute('height', String(size));
    svg.setAttribute('viewBox', meta.viewBox || '0 0 24 24');
    svg.setAttribute('fill', color);
    svg.setAttribute('role', 'img');
    svg.setAttribute('class', className ? 'reicon-brand ' + className : 'reicon-brand');

    for (const [k, v] of Object.entries(attrs)) {
      svg.setAttribute(k, String(v));
    }

    svg.innerHTML = svgContent;
    return svg;
  };

  icon.displayName = displayName;
  icon.hex = meta.hex || '';
  icon.title = meta.title || displayName;
  icon.slug = meta.slug || '';
  icon.svgContent = svgContent;

  icon.toSvg = (options) => {
    options = options || {};
    const color = options.color || 'currentColor';
    const size = options.size || 24;
    const className = options.className;
    const attrs = options.attrs || {};
    const vb = meta.viewBox || '0 0 24 24';

    const extraAttrs = Object.entries(attrs)
      .map(([k, v]) => escAttr(k) + '="' + escAttr(v) + '"')
      .join(' ');

    return '<svg xmlns="http://www.w3.org/2000/svg" width="' + escAttr(size) + '" height="' + escAttr(size) + '" viewBox="' + vb + '" fill="' + escAttr(color) + '" role="img" class="' + escAttr(className ? 'reicon-brand ' + className : 'reicon-brand') + '"' + (extraAttrs ? ' ' + extraAttrs : '') + '>' + svgContent + '</svg>';
  };

  return icon;
};

export { createIcon };
export default createIcon;
